package ru.truetv.launcher;
import android.app.*;
import android.content.*;
import android.os.*;
import android.widget.*;
import java.lang.reflect.*;
import ru.truetv.bridge.android.*;
/** Runs in the PHONE package. Does not own UiAutomation or grant storage permissions. */
public final class BridgePhoneCheck extends Instrumentation {
 private Object field(Object a,String n)throws Exception {Field f=a.getClass().getDeclaredField(n);f.setAccessible(true);return f.get(a);}
 public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle result=new Bundle();SendActivity activity=null;android.content.SharedPreferences known=null;java.util.Map<String,?> oldKnown=null;try{
  if(!Build.FINGERPRINT.contains("generic")&&!Build.MODEL.contains("Android SDK"))throw new AssertionError("VM only");known=getTargetContext().getSharedPreferences("totv_known",0);oldKnown=known.getAll();known.edit().clear().commit();ActivityMonitor monitor=new ActivityMonitor(SendActivity.class.getName(),null,false);addMonitor(monitor);Bundle phase=new Bundle();phase.putString("phase","phone_waiting_share");sendStatus(1,phase);activity=(SendActivity)waitForMonitorWithTimeout(monitor,25000);removeMonitor(monitor);if(activity==null)throw new AssertionError("No share target Activity");final SendActivity screen=activity;ListView list=(ListView)field(activity,"list");long end=SystemClock.uptimeMillis()+30000;while(list.getCount()==0&&SystemClock.uptimeMillis()<end)Thread.sleep(100);if(list.getCount()==0)throw new AssertionError("mDNS did not find TV");runOnMainSync(()->list.performItemClick(list.getChildAt(0),0,0));end=SystemClock.uptimeMillis()+25000;while((SendService.active==null||!SendService.active.confirming&&!SendService.active.done&&!SendService.active.status.contains("Waiting for TV approval")&&!SendService.active.status.contains("Ожидание подтверждения"))&&SystemClock.uptimeMillis()<end)Thread.sleep(100);SendService service=SendService.active;if(service==null)throw new AssertionError("Sender ended before confirmation");if(service.confirming){Button button=(Button)field(activity,"confirm");runOnMainSync(button::performClick);}runOnMainSync(screen::finish);activity=null;phase=new Bundle();phase.putString("phase","phone_backgrounded");sendStatus(1,phase);end=SystemClock.uptimeMillis()+45000;while(!service.done&&SystemClock.uptimeMillis()<end)Thread.sleep(100);if(!service.done||!(service.status.startsWith("Files sent: 2")||service.status.startsWith("Отправлено файлов: 2")))throw new AssertionError("Phone sender did not finish two-file batch: "+service.status);result.putBoolean("passed",true);result.putString("report","mDNS discovered TV; actual share target selected it; phone confirmed key/code; Activity finished while foreground service retained URI grants; result="+service.status);
 }catch(Throwable e){result.putBoolean("passed",false);result.putString("report",e.toString());}finally{if(known!=null&&oldKnown!=null){android.content.SharedPreferences.Editor e=known.edit().clear();for(java.util.Map.Entry<String,?> item:oldKnown.entrySet())if(item.getValue() instanceof Boolean)e.putBoolean(item.getKey(),(Boolean)item.getValue());e.commit();}if(activity!=null){SendActivity s=activity;runOnMainSync(s::finish);}}finish(result.getBoolean("passed")?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);}
}
